package app.dayora.task;
import java.security.Principal; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*;
@org.springframework.transaction.annotation.Transactional @RestController @RequestMapping("/api/workspaces/{workspaceId}/task-statuses") public class TaskStatusController {
 private final JdbcTemplate jdbc; private final app.dayora.realtime.AccountEvents events; public TaskStatusController(JdbcTemplate j,app.dayora.realtime.AccountEvents e){jdbc=j;events=e;}
 record Status(UUID id,UUID workspaceId,String name,String category,String color,int position,boolean isDefault,boolean archived){} record Input(String name,String category,String color,Boolean isDefault){} record Reorder(List<UUID> statusIds){} record Archive(UUID replacementStatusId){}
 private UUID owner(Principal p){return UUID.fromString(p.getName());} private void lock(UUID o){events.lock(o);} private void changed(UUID o){events.invalidate(o);}
 private void workspace(UUID o,UUID w){if(!Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workspace where owner_id=? and id=?)",Boolean.class,o,w)))throw new IllegalArgumentException("workspace unavailable");}
 private Status one(UUID o,UUID w,UUID id){return jdbc.query("select id,workspace_id,name,category,color,position,is_default,archived from task_status where owner_id=? and workspace_id=? and id=?",(r,n)->new Status(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getString(5),r.getInt(6),r.getBoolean(7),r.getBoolean(8)),o,w,id).stream().findFirst().orElseThrow(()->new NoSuchElementException("status unavailable"));}
 @GetMapping List<Status> list(@PathVariable UUID workspaceId,Principal p){UUID o=owner(p);workspace(o,workspaceId);return jdbc.query("select id,workspace_id,name,category,color,position,is_default,archived from task_status where owner_id=? and workspace_id=? order by position,id",(r,n)->new Status(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getString(5),r.getInt(6),r.getBoolean(7),r.getBoolean(8)),o,workspaceId);}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) Status create(@PathVariable UUID workspaceId,@RequestBody Input i,Principal p){UUID o=owner(p);lock(o);workspace(o,workspaceId);valid(i,false);if(Boolean.TRUE.equals(i.isDefault())&&!"UNSTARTED".equals(i.category()))throw new IllegalArgumentException("default must be UNSTARTED");lock(o);UUID id=UUID.randomUUID();if(Boolean.TRUE.equals(i.isDefault()))clearDefault(o,workspaceId);jdbc.update("insert into task_status(id,owner_id,workspace_id,name,category,color,position,is_default) values(?,?,?,?,?,?,coalesce((select max(position)+1 from task_status where workspace_id=?),0),?)",id,o,workspaceId,i.name().strip(),i.category(),i.color(),workspaceId,Boolean.TRUE.equals(i.isDefault()));changed(o);return one(o,workspaceId,id);}
 @PatchMapping("/{statusId}") Status patch(@PathVariable UUID workspaceId,@PathVariable UUID statusId,@RequestBody Input i,Principal p){UUID o=owner(p);lock(o);Status old=one(o,workspaceId,statusId);valid(i,true);String cat=i.category()==null?old.category():i.category();if(!cat.equals(old.category())&&Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from task where status_id=?)",Boolean.class,statusId)))throw new IllegalArgumentException("cannot change populated status category");guard(o,workspaceId,old,cat,i.isDefault()!=null?i.isDefault():old.isDefault(),i.isDefault()!=null&&i.isDefault());lock(o);if(Boolean.TRUE.equals(i.isDefault()))clearDefault(o,workspaceId);jdbc.update("update task_status set name=coalesce(?,name),category=?,color=coalesce(?,color),is_default=coalesce(?,is_default) where owner_id=? and workspace_id=? and id=?",i.name()==null?null:i.name().strip(),cat,i.color(),i.isDefault(),o,workspaceId,statusId);changed(o);return one(o,workspaceId,statusId);}
 @PostMapping("/reorder") List<Status> reorder(@PathVariable UUID workspaceId,@RequestBody Reorder r,Principal p){UUID o=owner(p);workspace(o,workspaceId);List<Status> all=list(workspaceId,p);if(r==null||r.statusIds()==null||r.statusIds().size()!=all.size()||new HashSet<>(r.statusIds()).size()!=all.size())throw new IllegalArgumentException("invalid status order");lock(o);for(int i=0;i<r.statusIds().size();i++)if(jdbc.update("update task_status set position=? where owner_id=? and workspace_id=? and id=?",i,o,workspaceId,r.statusIds().get(i))!=1)throw new IllegalArgumentException("invalid status order");changed(o);return list(workspaceId,p);}
 @PostMapping("/{statusId}/archive") Status archive(@PathVariable UUID workspaceId,@PathVariable UUID statusId,@RequestBody(required=false) Archive a,Principal p){UUID o=owner(p);lock(o);Status s=one(o,workspaceId,statusId);removable(o,workspaceId,s);UUID replacement=a==null?null:a.replacementStatusId();if(replacement!=null&&replacement.equals(statusId))throw new IllegalArgumentException("replacement cannot self");long used=jdbc.queryForObject("select count(*) from task where status_id=?",Long.class,statusId);if(used>0){if(replacement==null)throw new IllegalArgumentException("replacement required");Status r=one(o,workspaceId,replacement);if(r.archived())throw new IllegalArgumentException("replacement archived");lock(o);String legacy=legacy(r.category());jdbc.update("update task set status_id=?,status=?,completed_at=case when ?='DONE' then coalesce(completed_at,current_timestamp) else null end,revision=revision+1,updated_at=current_timestamp where status_id=?",r.id(),legacy,legacy,s.id());}else lock(o);jdbc.update("update task_status set archived=true where owner_id=? and workspace_id=? and id=?",o,workspaceId,statusId);changed(o);return one(o,workspaceId,statusId);}
 @PostMapping("/{statusId}/restore") Status restore(@PathVariable UUID workspaceId,@PathVariable UUID statusId,Principal p){UUID o=owner(p);one(o,workspaceId,statusId);lock(o);jdbc.update("update task_status set archived=false where owner_id=? and workspace_id=? and id=?",o,workspaceId,statusId);changed(o);return one(o,workspaceId,statusId);}
 @DeleteMapping("/{statusId}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID workspaceId,@PathVariable UUID statusId,Principal p){UUID o=owner(p);lock(o);Status s=one(o,workspaceId,statusId);removable(o,workspaceId,s);if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from task where status_id=? )",Boolean.class,statusId)))throw new IllegalArgumentException("status in use; archive instead");lock(o);jdbc.update("delete from task_status where owner_id=? and workspace_id=? and id=?",o,workspaceId,statusId);changed(o);}
 private void clearDefault(UUID o,UUID w){jdbc.update("update task_status set is_default=false where owner_id=? and workspace_id=?",o,w);}
 private void removable(UUID o,UUID w,Status s){if(s.isDefault())throw new IllegalArgumentException("switch default first");remaining(o,w,s);}
 private void remaining(UUID o,UUID w,Status s){if(!s.archived()&&Set.of("UNSTARTED","COMPLETED").contains(s.category())&&jdbc.queryForObject("select count(*) from task_status where owner_id=? and workspace_id=? and category=? and not archived and id<>?",Long.class,o,w,s.category(),s.id())==0)throw new IllegalArgumentException("last active category required");}
 private void guard(UUID o,UUID w,Status s,String c,boolean def,boolean switching){if(def&&(s.archived()||!"UNSTARTED".equals(c)))throw new IllegalArgumentException("invalid default");if(!s.category().equals(c)){remaining(o,w,s);if(s.isDefault())throw new IllegalArgumentException("switch default first");}if(s.isDefault()&&!def)throw new IllegalArgumentException("switch default first");}
 private static String legacy(String c){return switch(c){case "UNSTARTED"->"TODO";case "STARTED"->"IN_PROGRESS";case "COMPLETED"->"DONE";default->"CANCELED";};}
 private static void valid(Input i,boolean partial){if(i==null||(!partial&&(i.name()==null||i.category()==null))||(i.name()!=null&&(i.name().isBlank()||i.name().strip().length()>120))||(i.category()!=null&&!Set.of("UNSTARTED","STARTED","COMPLETED","CANCELED").contains(i.category()))||(i.color()!=null&&!i.color().matches("#[0-9A-Fa-f]{6}")))throw new IllegalArgumentException("invalid status");}
}
